package experiment

import (
	"context"
	"fmt"
	"math"
	"reflect"

	"github.com/TimLai666/coimnet/experiment/nav2d"
	"github.com/TimLai666/coimnet/learning"
)

// AttributionConclusion is the only conclusion sentence the report may carry
// (master plan 14.4): a drop after freezing or removing the core shows
// dependence on it, not that the original wiring is superior.
const AttributionConclusion = "A drop after freezing or removing the core shows dependence on it, not that the original wiring is superior."

// AttributionConfig is one complete seven-group attribution protocol: the
// environment, the shared seeds and schedule, the policy sizes, the learning
// rate, the shared evaluation batch, the groups to run and the pre-registered
// comparison.
type AttributionConfig struct {
	Env          nav2d.Config  `json:"env"`           // Task must be set
	Seeds        []uint64      `json:"seeds"`         // >= 3, distinct
	Episodes     int           `json:"episodes"`      // 1..10000, the same schedule for every group
	Hidden       int           `json:"hidden"`        // 4..128
	Recurrent    int           `json:"recurrent"`     // 1..Hidden
	LearningRate float64       `json:"learning_rate"` // > 0
	EvalEpisodes int           `json:"eval_episodes"` // 1..1000
	Groups       []string      `json:"groups"`        // subset of AttributionGroups(), no duplicates, must contain normal
	Comparison   PreRegistered `json:"comparison"`    // Method paired_bootstrap, Baseline normal, Interval in (0,1), Resamples >= 100
}

// Validate checks the protocol without running anything: the environment task
// must be declared and accepted by nav2d.New, seeds must be at least three
// and distinct, every budget and size must sit inside its declared range, the
// group list must be a duplicate-free subset of AttributionGroups() that
// contains normal, and the comparison must be the pre-registered paired
// bootstrap against the normal baseline.
func (c AttributionConfig) Validate() error {
	if c.Env.Task == "" {
		return fmt.Errorf("attribution config env: task must be set")
	}
	if _, err := nav2d.New(c.Env); err != nil {
		return fmt.Errorf("attribution config env: %w", err)
	}
	if len(c.Seeds) < 3 {
		return fmt.Errorf("attribution config declares %d seeds, want at least 3", len(c.Seeds))
	}
	seenSeed := map[uint64]bool{}
	for _, seed := range c.Seeds {
		if seenSeed[seed] {
			return fmt.Errorf("attribution config declares duplicate seed %d", seed)
		}
		seenSeed[seed] = true
	}
	if c.Episodes < 1 || c.Episodes > 10000 {
		return fmt.Errorf("attribution config episodes %d, want a value in [1, 10000]", c.Episodes)
	}
	if c.Hidden < 4 || c.Hidden > 128 {
		return fmt.Errorf("attribution config hidden %d, want a value in [4, 128]", c.Hidden)
	}
	if c.Recurrent < 1 || c.Recurrent > c.Hidden {
		return fmt.Errorf("attribution config recurrent %d, want a value in [1, %d]", c.Recurrent, c.Hidden)
	}
	if !finite(c.LearningRate) || c.LearningRate <= 0 {
		return fmt.Errorf("attribution config learning rate %v must be finite and positive", c.LearningRate)
	}
	if c.EvalEpisodes < 1 || c.EvalEpisodes > 1000 {
		return fmt.Errorf("attribution config eval episodes %d, want a value in [1, 1000]", c.EvalEpisodes)
	}
	known := map[string]bool{}
	for _, group := range AttributionGroups() {
		known[group] = true
	}
	used := map[string]bool{}
	normal := false
	for _, group := range c.Groups {
		if !known[group] {
			return fmt.Errorf("attribution config declares unknown group %q", group)
		}
		if used[group] {
			return fmt.Errorf("attribution config declares duplicate group %q", group)
		}
		used[group] = true
		if group == AttributionNormal {
			normal = true
		}
	}
	if !normal {
		return fmt.Errorf("attribution config declares no %q group", AttributionNormal)
	}
	if c.Comparison.Method != ComparisonPairedBootstrap {
		return fmt.Errorf("attribution comparison: unsupported method %q", c.Comparison.Method)
	}
	if c.Comparison.Baseline != AttributionNormal {
		return fmt.Errorf("attribution comparison: unsupported baseline %q", c.Comparison.Baseline)
	}
	if c.Comparison.Interval <= 0 || c.Comparison.Interval >= 1 {
		return fmt.Errorf("attribution comparison: interval must be strictly between 0 and 1, got %g", c.Comparison.Interval)
	}
	if c.Comparison.Resamples < 100 {
		return fmt.Errorf("attribution comparison: resamples %d, want at least 100", c.Comparison.Resamples)
	}
	return nil
}

// DefaultAttributionConfig returns the declared default protocol: the
// avoid_obstacles task, seeds 1, 2 and 3, 60 training episodes, a 16-node
// hidden block with 4 recurrent sources, learning rate 0.05, 20 evaluation
// maps, all seven groups and a 1000-resample 95% paired bootstrap against
// normal.
func DefaultAttributionConfig() AttributionConfig {
	return AttributionConfig{
		Env:          nav2d.Config{Task: nav2d.TaskAvoidObstacles},
		Seeds:        []uint64{1, 2, 3},
		Episodes:     60,
		Hidden:       16,
		Recurrent:    4,
		LearningRate: 0.05,
		EvalEpisodes: 20,
		Groups:       AttributionGroups(),
		Comparison: PreRegistered{
			Method:    ComparisonPairedBootstrap,
			Interval:  0.95,
			Baseline:  AttributionNormal,
			Resamples: 1000,
		},
	}
}

// CoreOnlyChecks is the troubleshooting list attached to core_only when it
// did not learn (Seen.ExpertAgreement <= Before.ExpertAgreement). It never
// changes the model; the periphery is never enlarged.
type CoreOnlyChecks struct {

package experiment

import (
	"fmt"
	"math"
)

// ContinualSchemaVersion identifies the preregistered continual-matrix protocol.
const ContinualSchemaVersion = "coimnet-continual-matrix/v1"

// GeneratorDelayedCorrelation names the only task generator a protocol may use.
const GeneratorDelayedCorrelation = "delayed-correlation/v1"

// Stage kinds a continual protocol may declare.
const (
	StageTrainTask  = "train_task"
	StageRuleChange = "rule_change"
)

// MetricNegMSE expects the "bigger is better" evaluation score.
const MetricNegMSE = "neg_mse"

// ComparisonPairedBootstrap is the only preregistered comparison method.
const ComparisonPairedBootstrap = "paired_bootstrap"

// BaselineIndependent re-runs each task freshly trained in isolation.
const BaselineIndependent = "independent"

// TaskSpec names one task of a versioned generator. delayed-correlation/v1
// takes "delay" (integer 1..8), "channel" (integer 0..7) and an optional
// "gain" (nonzero, |gain| <= 1, default 0.4 when absent).
type TaskSpec struct {
	Name      string             `json:"name"`
	Generator string             `json:"generator"`
	Params    map[string]float64 `json:"params,omitempty"`
}

// Stage is one training or intervention window. Budget is in training
// episodes; a rule_change stage must have Budget 0.
type Stage struct {
	Kind   string `json:"kind"`
	Task   string `json:"task"`
	Budget uint64 `json:"budget"`
}

// StateSwitch is the alternative chemical state (region x channel) the same
// individual is re-evaluated under, as a "temporarily suppressed, not
// forgotten" control.
type StateSwitch struct {
	Concentration [][]float64 `json:"concentration"`
}

// Evaluation fixes how every post-stage matrix cell is measured.
type Evaluation struct {
	Episodes       int          `json:"episodes"`
	FixedChemistry bool         `json:"fixed_chemistry"`
	StateSwitch    *StateSwitch `json:"state_switch,omitempty"`
	Metric         string       `json:"metric"`
}

// PreRegistered declares the comparison method and its uncertainty interval
// before any matrix is produced.
type PreRegistered struct {
	Method    string  `json:"method"`
	Interval  float64 `json:"interval"`
	Baseline  string  `json:"baseline"`
	Resamples int     `json:"resamples"`
}

// ContinualProtocol is the complete preregistered continual-learning protocol.
type ContinualProtocol struct {
	Tasks      []TaskSpec     `json:"tasks"`
	Stages     []Stage        `json:"stages"`
	Seeds      []uint64       `json:"seeds"`
	Evaluation Evaluation     `json:"evaluation"`
	Comparison *PreRegistered `json:"comparison,omitempty"`
}

// Validate rejects a protocol whose matrix or attribution could be undefined.
func (p ContinualProtocol) Validate() error {
	if len(p.Tasks) == 0 {
		return fmt.Errorf("tasks: at least one task required")
	}
	seenTasks := make(map[string]int, len(p.Tasks))
	for i, ts := range p.Tasks {
		if ts.Name == "" {
			return fmt.Errorf("task %d: name must not be empty (duplicate names are rejected)", i)
		}
		if prev, ok := seenTasks[ts.Name]; ok {
			return fmt.Errorf("task %d: duplicate name %q (already task %d)", i, ts.Name, prev)
		}
		seenTasks[ts.Name] = i
		if ts.Generator != GeneratorDelayedCorrelation {
			return fmt.Errorf("task %q: unsupported generator %q", ts.Name, ts.Generator)
		}
		if _, ok := ts.Params["delay"]; !ok {
			return fmt.Errorf("task %q: param delay is required", ts.Name)
		}
		if _, ok := ts.Params["channel"]; !ok {
			return fmt.Errorf("task %q: param channel is required", ts.Name)
		}
		for key, v := range ts.Params {
			switch key {
			case "delay":
				if v != math.Trunc(v) || v < 1 || v > 8 {
					return fmt.Errorf("task %q: param delay must be an integer in 1..8, got %v", ts.Name, v)
				}
			case "channel":
				if v != math.Trunc(v) || v < 0 || v > 7 {
					return fmt.Errorf("task %q: param channel must be an integer in 0..7, got %v", ts.Name, v)
				}
			case "gain":
				if math.IsNaN(v) || math.IsInf(v, 0) || v == 0 || math.Abs(v) > 1 {
					return fmt.Errorf("task %q: param gain must be non-zero with |gain| <= 1, got %v", ts.Name, v)
				}
			default:
				return fmt.Errorf("task %q: unsupported param %q", ts.Name, key)
			}
		}
	}
	if len(p.Stages) == 0 {
		return fmt.Errorf("stages: at least one stage required")
	}
	for i, st := range p.Stages {
		if st.Kind != StageTrainTask && st.Kind != StageRuleChange {
			return fmt.Errorf("stage %d: unsupported kind %q", i, st.Kind)
		}
		if _, ok := seenTasks[st.Task]; !ok {
			return fmt.Errorf("stage %d: unknown task %q", i, st.Task)
		}
		if st.Kind == StageRuleChange && st.Budget != 0 {
			return fmt.Errorf("stage %d: rule_change budget must be 0, got %d", i, st.Budget)
		}
		if st.Kind == StageTrainTask && st.Budget > 1000000 {
			return fmt.Errorf("stage %d: train_task budget %d exceeds limit 1000000", i, st.Budget)
		}
	}
	if len(p.Seeds) < 3 {
		return fmt.Errorf("seeds: at least 3 required, got %d", len(p.Seeds))
	}
	seenSeeds := make(map[uint64]bool, len(p.Seeds))
	for _, seed := range p.Seeds {
		if seenSeeds[seed] {
			return fmt.Errorf("seeds: duplicate seed %d", seed)
		}
		seenSeeds[seed] = true
	}
	if p.Evaluation.Episodes < 1 || p.Evaluation.Episodes > 10000 {
		return fmt.Errorf("evaluation: episodes must be between 1 and 10000, got %d", p.Evaluation.Episodes)
	}
	if p.Evaluation.Metric != MetricNegMSE {
		return fmt.Errorf("evaluation: unsupported metric %q", p.Evaluation.Metric)
	}
	if sw := p.Evaluation.StateSwitch; sw != nil {
		if len(sw.Concentration) == 0 {
			return fmt.Errorf("state_switch: concentration must not be empty")
		}
		width := len(sw.Concentration[0])
		for i, row := range sw.Concentration {
			if len(row) != width {
				return fmt.Errorf("state_switch: row %d has length %d, want %d", i, len(row), width)
			}
			for _, v := range row {
				if math.IsNaN(v) || math.IsInf(v, 0) {
					return fmt.Errorf("state_switch: value %g is not finite", v)
				}
				if v < 0 {
					return fmt.Errorf("state_switch: value %g is negative", v)
				}
			}
		}
	}
	if c := p.Comparison; c != nil {
		if c.Method != ComparisonPairedBootstrap {
			return fmt.Errorf("comparison: unsupported method %q", c.Method)
		}
		if c.Interval <= 0 || c.Interval >= 1 {
			return fmt.Errorf("comparison: interval must be strictly between 0 and 1, got %g", c.Interval)
		}
		if c.Baseline != BaselineIndependent {
			return fmt.Errorf("comparison: unsupported baseline %q", c.Baseline)
		}
		if c.Resamples < 100 || c.Resamples > 100000 {
			return fmt.Errorf("comparison: resamples must be between 100 and 100000, got %d", c.Resamples)
		}
	}
	return nil
}

// TaskWidth is the input width every task of the protocol shares: 1 + the
// largest declared channel. Only valid after Validate.
func (p ContinualProtocol) TaskWidth() int {
	width := 1
	for _, ts := range p.Tasks {
		if c := int(ts.Params["channel"]); c+1 > width {
			width = c + 1
		}
	}
	return width
}

// TaskIndex returns the position of the named task or -1.
func (p ContinualProtocol) TaskIndex(name string) int {
	for i, ts := range p.Tasks {
		if ts.Name == name {
			return i
		}
	}
	return -1
}

